import{neuralFigure,neuralSVG,nt}from './neural-figures.js?v=20261023-physicscomplete01';
const phase=(p,n)=>Math.min(n-1,Math.floor(Math.max(0,Math.min(1,p))*n));const make=(title,steps,note,render)=>({title,steps,note,render,duration:12});
export const neuralFilms={
 'neuro-control':make('Homeostasis: a corrective response',['An internal value departs from its optimum.','A receptor detects the change.','A coordination centre processes the information.','An effector response moves the value back towards optimum.'],'Generic control example in arbitrary units, not a specific hormone or patient simulation. Stages overlap in living control systems; reset returns the example to its starting deviation.',p=>neuralFigure({kind:'control',value:p<.6?8:8-3*Math.min(1,(p-.6)/.4),result:'Detect → coordinate → respond; regulation maintains suitable internal conditions.'})),
 'neuro-neuron':make('Nervous response: trace the signal',['A receptor detects a stimulus.','An electrical impulse carries information towards the CNS.','The CNS coordinates the outgoing signal.','An effector produces a response.'],'The marker traces an impulse, not a visible substance or blood cell. Direction and sequence are schematic; displayed speed is not measured neural speed.',p=>{let x=70+p*430;return neuralFigure({kind:'neuron'}).replace('</svg>',`<circle cx="${x}" cy="190" r="9" fill="#f2cca1"/></svg>`);} ),
 'neuro-reflex':make('Spinal reflex: incoming to outgoing',['A receptor detects the stimulus.','A sensory neurone carries the incoming impulse.','Communication crosses the first synapse.','A relay neurone carries information within the spinal cord.','Communication crosses the second synapse.','A motor neurone carries the outgoing impulse.','The effector produces the immediate response.'],'Slow route summary; electrical impulses along neurones and chemical transmission at these synapses. Immediate response does not await conscious choice; later awareness is possible.',p=>neuralFigure({kind:'reflex',step:phase(p,7)})),
 'neuro-synapse':make('Chemical synapse: electrical to chemical to electrical',['An electrical impulse arrives at the ending.','Transmitter is released from the sending ending.','Transmitter diffuses across the enlarged cleft.','Transmitter binds receptors on the receiving membrane.','The receiving neurone can produce an electrical impulse.'],'Simplified excitatory chemical-synapse example; not every biological junction. Molecules/gap and stage durations are symbolic. Release and binding are required in this illustrated route.',p=>neuralFigure({kind:'synapse',step:[1,2,3,4,5][phase(p,5)],progress:(p*5)%1})),
 'neuro-reaction':make('Ruler catch: prepare, release, catch, record',['Align the ruler zero with the catching fingers.','Release without a predictable countdown.','Catch and read the fall distance.','Repeat, use the supplied conversion and compare condition means.'],'Worked practical preparation, not a live personal timer or apparatus competency certificate. The physical school practical uses matched controls and a harmless task. Film time is symbolic.',p=>{let drop=phase(p,4)===0?0:Math.min(100,(p-.25)*200);return neuralSVG(`<g transform="translate(0,${drop})"><rect x="235" y="30" width="70" height="210" rx="8" fill="#d7bf98"/>${[0,5,10,15,20].map((n,i)=>`<path d="M235 ${45+i*40}h18" stroke="#35516a"/>`+`<text x="270" y="${51+i*40}" fill="#182e44" font-size="16">${n}</text>`).join('')}</g><path d="M150 270h80m80 0h100" stroke="#e7b79d" stroke-width="20" stroke-linecap="round"/>`+nt(280,370,'cm on ruler; use supplied conversion table',18),'Schematic ruler falls and is caught at the fingers.');})
};
